-- 0155: construction arcs for توب شدد عقب طول صير — every Qurʾānic use of the 12 lemmas placed in one arc — model كشف; every example checked in the muṣḥaf, every lemma in AL, every count against its verses.
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:taba:ila', 'توب', '3a455b6f1e1915d19ca0493fa2', NULL, 'تَابَ + إِلَى', 'إلى', 0, 12, '["2:54", "5:74", "7:143", "11:3", "11:52", "11:61", "11:90", "24:31", "25:71", "46:15", "66:4", "66:8"]', 'رجوعٌ ← رجوعُ العبدِ عن الذنب ← إلى اللهِ غايةً', 'turn back → away from the wrong, and home to God', 'The one who turns is always the person, and God is where he turns to. When God is the subject, the Qurʾān never uses إلى — it uses على (next arc).', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_3806218aa7fb9ccc", "lex:ibn_manzur_lisan_arab:blk_lsn_4133ac08d1677d7c", "lex:lane_lexicon:blk_lane_d499265863bca32a", "lex:raghib_mufradat:blk_mfr_7f6f2db8cd712f15", "lex:raghib_mufradat:blk_mfr_9a520f6a74415952"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:taba:ala', 'توب', '3a455b6f1e1915d19ca0493fa2', NULL, 'تَابَ + عَلَى', 'على', 0, 23, '["2:37", "2:54", "2:128", "2:160", "2:187", "3:128", "4:17", "4:26", "4:27", "5:39", "5:71", "9:15", "9:27", "9:102", "9:106", "9:117", "9:118", "20:122", "33:24", "33:73", "58:13", "73:20"]', 'رجوعٌ ← رجوعُ اللهِ على العبدِ بالقبولِ والرحمة ← (أو توفيقُه للتوبة)', 'turn back → God turns toward the person in mercy, and accepts him', 'Here God is always the subject. One event, two names: the person تاب إلى God, and God تاب على him (al-Rāghib). al-Jawharī adds a second sense — God helped him to turn — which fits 9:118.', NULL, '[{"kind": "sense", "label": "accepted_his_turning", "refs": ["2:37", "2:54", "2:128", "2:160", "2:187", "3:128", "4:17", "4:26", "4:27", "5:39", "5:71", "9:15", "9:27", "9:102", "9:106", "9:117", "20:122", "33:24", "33:73", "58:13", "73:20"]}, {"kind": "sense", "label": "helped_him_to_turn", "refs": ["9:118"], "note_en": "ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْ — al-Ālūsī: وفّقهم للتوبة"}]', '["lex:lane_lexicon:blk_lane_f6ea74da3c384e61", "lex:ibn_manzur_lisan_arab:blk_lsn_2f61478ed716f946", "lex:raghib_mufradat:blk_mfr_72ffee1e445b4afe", "lex:raghib_mufradat:blk_mfr_9a520f6a74415952", "lex:jawhari_sihah:blk_sih_17031c4d9574309d", "lex:zabidi_taj_arus:blk_taj_b02b773455da4f5e", "tafsir:alusi:9:118"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:taba:bare', 'توب', '3a455b6f1e1915d19ca0493fa2', NULL, 'تَابَ (بلا حرف)', NULL, 0, 28, '["2:160", "2:279", "3:89", "4:16", "4:17", "4:18", "4:146", "5:34", "5:39", "6:54", "7:153", "9:3", "9:5", "9:11", "9:74", "9:118", "9:126", "11:112", "16:119", "19:60", "20:82", "24:5", "25:70", "25:71", "28:67", "40:7", "49:11", "85:10"]', 'رجوعٌ ← رجوعُ العبدِ عن ذنبه ← والغايةُ مفهومة', 'turn back → from the wrong; where to is left unsaid', 'Same sense as with إلى; the goal is just not named, because it is clear. Phrases that often follow — مِن قَرِيبٍ, مِنۢ بَعۡدِ ذَٰلِكَ — say WHEN, not where; they are not the verb''s particle. The subject is always the person.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_3806218aa7fb9ccc", "lex:fayyumi_misbah_munir:blk_msb_90c7611183a619be", "lex:raghib_mufradat:blk_mfr_dab5f6b697acc4f5", "lex:raghib_mufradat:blk_mfr_2599843e71a09969"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:tawb:idafa', 'توب', 'a8886e1216f97189f836165615', NULL, 'قَابِلِ + التَّوْب (إضافة)', NULL, 1, 1, '["40:3"]', 'رجوعٌ ← التَّوبُ مصدرًا ← يقبلُه اللهُ صفةً ثابتة', 'the turning back → named as a thing God takes in, always', 'قَابِلِ ٱلتَّوۡبِ is the noun form of يَقۡبَلُ ٱلتَّوۡبَةَ (42:25). al-Zamakhsharī: it names a lasting quality of God, not one act at one time. التَّوۡب is the maṣdar, or a plural of تَوۡبَة (Lisān).', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_2f61478ed716f946", "lex:maqayis_lugha:blk_mqy_3eddbe8857c35f3f", "tafsir:zamakhshari:40:3", "tafsir:ibn_ashur:40:3"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:tawba:qabul_an', 'توب', '796f455db3b68132b6fa975e20', NULL, 'قَبِلَ + التَّوْبَة (+ عَن)', 'عن', 1, 3, '["3:90", "9:104", "42:25"]', 'رجوعُ العبد ← يُقبَلُ منه ← مع التجاوزِ عن ذنبه', 'a person''s turning → received by God, and the sin passed over', 'Two readings of عن: it brings in the sense of passing over the sins (al-Ālūsī), or it simply means مِن, "from" (al-Rāzī). In 3:90 the pair is denied: their turning will not be received.', NULL, '[{"kind": "harf", "label": "an", "refs": ["9:104", "42:25"]}, {"kind": "polarity", "label": "negated_idafa_to_doer", "refs": ["3:90"]}]', '["tafsir:alusi:9:104", "tafsir:razi:9:104", "lex:raghib_mufradat:blk_mfr_ac01802d550a7de6"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:tawba:ala_lam', 'توب', '796f455db3b68132b6fa975e20', NULL, 'التَّوْبَة + عَلَى اللهِ + لِـ', 'على', 0, 2, '["4:17", "4:18"]', 'رجوعٌ ← قبولُ التوبة ← وعدٌ ألزمَه اللهُ نفسَه لِمَن…', 'the turning back → a promise God has taken on Himself, for those who…', 'Here التوبة means God''s acceptance of the turning (al-Ālūsī). على marks what is binding — by His own promise (al-Zamakhsharī); لِـ names who it is for. 4:18 denies it to those who wait until death.', NULL, NULL, '["tafsir:alusi:4:17", "tafsir:zamakhshari:4:17", "tafsir:ibn_ashur:4:17"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:tawba:min', 'توب', '796f455db3b68132b6fa975e20', NULL, 'تَوْبَةً + مِنَ اللهِ', 'من', 0, 1, '["4:92"]', 'رجوعٌ ← رجوعُ اللهِ بالرحمة ← تخفيفٌ يأتي من عنده', 'a turning → that comes from God: His mercy, easing the law', 'مِن shows the turning starts from God, so it means His acceptance and mercy, not the person''s repentance (Ibn ʿĀshūr). The fast is laid down as that mercy (al-Zamakhsharī).', NULL, NULL, '["tafsir:ibn_ashur:4:92", "tafsir:zamakhshari:4:92"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:توب:tawba:mutlaq', 'توب', '796f455db3b68132b6fa975e20', NULL, 'تُوبُوا … تَوْبَةً (مفعول مطلق موصوف)', NULL, 0, 1, '["66:8"]', 'رجوعٌ ← تسميةُ الرجوعِ نفسِه ← ليُوصَفَ: نصوحًا', 'the turning back → named again so it can be described: sincere', 'The verb already says "turn back to God"; the maṣdar adds no new sense — it makes room for نَصُوحًا, a turning with no plan to go back (Ibn ʿĀshūr).', NULL, NULL, '["lex:lane_lexicon:blk_lane_d499265863bca32a", "tafsir:ibn_ashur:66:8", "tafsir:zamakhshari:66:8"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadid:plain', 'شدد', 'd598d16f55259b05ab7239513e', NULL, 'شَدِيد (نعتًا أو خبرًا)', NULL, 0, 37, '["3:4", "3:56", "6:124", "7:164", "10:70", "11:80", "11:102", "12:48", "14:2", "14:7", "17:5", "17:58", "18:2", "22:2", "23:77", "27:21", "27:33", "33:11", "34:46", "35:7", "35:10", "38:26", "41:27", "42:16", "42:26", "48:16", "50:26", "57:20", "57:25", "58:15", "59:14", "65:8", "65:10", "66:6", "72:8", "78:12", "85:12"]', 'قوّةٌ في الشيء ← شدٌّ وإحكام ← صعبٌ قويٌّ في ذاته', 'tied tight → hard and strong in itself', 'Nothing follows the word: the thing named — a punishment, a force, a quake — is itself severe.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_fa4c8080f0d6c345", "lex:lane_lexicon:blk_lane_9fbfd2d8b2782dc6", "lex:ibn_manzur_lisan_arab:blk_lsn_33efc7e3ad2b07b2"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadid:idafa', 'شدد', 'd598d16f55259b05ab7239513e', NULL, 'شَدِيدُ + مضاف إليه', NULL, 0, 17, '["2:165", "2:196", "2:211", "3:11", "5:2", "5:98", "8:13", "8:25", "8:48", "8:52", "13:6", "13:13", "40:3", "40:22", "53:5", "59:4", "59:7"]', 'قوّة ← صفةٌ لصاحبها ← تُضافُ إلى ما اشتدّ منه: شديدٌ عقابُه', 'severe → said of the One, and the iḍāfa names what is severe: His punishment', 'The adjective describes God (Jibrīl in 53:5), but what is severe is the noun after it: شَدِيدُ ٱلۡعِقَابِ = "whose punishment is severe" (al-Zamakhsharī). This iḍāfa only lightens the wording; the second noun is the real subject (Ibn ʿĀshūr).', NULL, '[{"kind": "object_semantics", "label": "punishment", "refs": ["2:165", "2:196", "2:211", "3:11", "5:2", "5:98", "8:13", "8:25", "8:48", "8:52", "13:6", "40:3", "40:22", "59:4", "59:7"]}, {"kind": "object_semantics", "label": "power", "refs": ["13:13", "53:5"]}]', '["tafsir:zamakhshari:40:3", "tafsir:ibn_ashur:40:3", "lex:lane_lexicon:blk_lane_9fbfd2d8b2782dc6", "lex:raghib_mufradat:blk_mfr_f71d7ce63756b754"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadid:ala', 'شدد', 'd598d16f55259b05ab7239513e', NULL, 'أَشِدَّاءُ + عَلَى', 'على', 0, 1, '["48:29"]', 'قوّة ← صلابةٌ في النفس ← تُوجَّهُ على الخصم', 'strong → firm and hard, turned against the other side', 'على aims the hardness at someone (Lane: شديد على قومه, "hard toward his people"). The verse sets it against رُحَمَآءُ بَيۡنَهُمۡ: hard toward the enemy, gentle among themselves.', NULL, NULL, '["lex:lane_lexicon:blk_lane_9fbfd2d8b2782dc6", "lex:ibn_manzur_lisan_arab:blk_lsn_33efc7e3ad2b07b2", "tafsir:ibn_ashur:48:29"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadid:lam', 'شدد', 'd598d16f55259b05ab7239513e', NULL, 'لِـ … لَشَدِيد', 'لـ', 0, 1, '["100:8"]', 'شدٌّ ← شدُّ اليدِ على المال ← بخيلٌ لأجلِ حبِّه (أو: قويُّ الحبِّ له)', 'tied tight → tight-fisted because he loves wealth — or strong in loving it', 'Two readings. (1) لِـ gives the reason and شديد = miserly: "out of love of wealth he is tight-fisted" (al-Zajjāj in Lisān; al-Rāzī). (2) لِـ = "in", شديد = strong: "he is intense in his love of wealth" (al-Zamakhsharī, as quoted by al-Ālūsī, who thinks it more likely).', NULL, '[{"kind": "reading", "label": "miserly_lam_of_reason", "refs": ["100:8"]}, {"kind": "reading", "label": "strong_lam_as_fi", "refs": ["100:8"]}]', '["lex:ibn_manzur_lisan_arab:blk_lsn_f4fcd938e6834ae9", "lex:maqayis_lugha:blk_mqy_ab23cc2a3456009d", "lex:lane_lexicon:blk_lane_9fbfd2d8b2782dc6", "tafsir:razi:100:8", "tafsir:alusi:100:8"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadda:direct', 'شدد', '3f55c0cc3dd6f3d9b639739bda', NULL, 'شَدَّ + مفعول', NULL, 1, 3, '["38:20", "47:4", "76:28"]', 'شدُّ العُقدة ← إيثاقُها ← تقويةُ الشيءِ وإحكامُه', 'tie tight → make firm and strong', 'Literal in 47:4 (tie the bonds); of the body''s frame in 76:28; of a kingdom in 38:20 — the knot becomes strength (Lisān: شدّ الله ملكه = قوّاه).', NULL, '[{"kind": "object_semantics", "label": "bond", "refs": ["47:4"]}, {"kind": "object_semantics", "label": "body_frame", "refs": ["76:28"]}, {"kind": "object_semantics", "label": "kingdom", "refs": ["38:20"]}]', '["lex:maqayis_lugha:blk_mqy_fa4c8080f0d6c345", "lex:ibn_manzur_lisan_arab:blk_lsn_b8e19a14dacb5900", "lex:ibn_manzur_lisan_arab:blk_lsn_73dd3f1132a4a38a", "lex:raghib_mufradat:blk_mfr_96d1608bef738e9a", "lex:lane_lexicon:blk_lane_cc65a837c0a94f72"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadda:bi', 'شدد', '3f55c0cc3dd6f3d9b639739bda', NULL, 'شَدَّ + مفعول + بِـ', 'بـ', 1, 2, '["20:31", "28:35"]', 'شدٌّ ← ربطُ شيءٍ بشيء ← تقويةُ الأوّلِ بالثاني', 'tie tight → strengthen one thing by binding another to it', 'The object is what grows strong (Mūsā''s back, his arm); بِـ names the helper (Hārūn). The books give "strengthen" and quote 20:31 but do not explain the بِـ.', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_d3791c1a05e270cc", "lex:ibn_manzur_lisan_arab:blk_lsn_73dd3f1132a4a38a", "lex:zabidi_taj_arus:blk_taj_36aefadba98c080b", "tafsir:ibn_ashur:28:35"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:شدد:shadda:ala', 'شدد', '3f55c0cc3dd6f3d9b639739bda', NULL, 'شَدَّ + عَلَى', 'على', 0, 1, '["10:88"]', 'شدٌّ ← إحكامُ الغِطاءِ فوقَ الشيء ← طَبعٌ على القلوب', 'bind tight → bind shut over the hearts: seal them', 'The books read وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ as اطبع على قلوبهم, "seal their hearts" (Lane, Lisān, Tāj; al-Ālūsī: make them hard and seal them). Ibn ʿĀshūr alone takes it from الشِّدَّة, hardship: "bring distress into their hearts". Not Form II شدّد عليه, "be hard on".', NULL, '[{"kind": "reading", "label": "seal", "refs": ["10:88"]}, {"kind": "reading", "label": "hardship_ibn_ashur", "refs": ["10:88"]}]', '["lex:lane_lexicon:blk_lane_cc65a837c0a94f72", "lex:ibn_manzur_lisan_arab:blk_lsn_f4fcd938e6834ae9", "lex:zabidi_taj_arus:blk_taj_ec6dccbf42b53d11", "tafsir:alusi:10:88", "tafsir:ibn_ashur:10:88"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عقب:aqaba:bi', 'عقب', 'c1db74b2f90ad230b75165ed7e', NULL, 'عَاقَبَ + بِـ (بِمِثْلِ مَا…)', 'بـ', 0, 5, '["16:126", "22:60"]', 'إتيانُ الشيء بعد غيره ← جزاءٌ يأتي عَقِبَ الفعل ← بمثلِه لا يزيد', 'come after → pay back after a wrong, with exactly its like', 'بِـ carries what the payback is made of — بِمِثۡلِ, "the like of". In عُوقِبۡتُم بِهِۦ the first wrong is also called "punishment" only to match the wording (al-Zamakhsharī: المزاوجة; Lane).', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_7ca2138ca389ba49", "lex:maqayis_lugha:blk_mqy_f5981540d7d15737", "lex:lane_lexicon:blk_lane_12dc1ad47a01ae73", "lex:ibn_manzur_lisan_arab:blk_lsn_59c16f78a16b0432", "lex:raghib_mufradat:blk_mfr_4f82fb683d7e3c75", "tafsir:zamakhshari:16:126", "tafsir:ibn_ashur:16:126"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عقب:aqaba:turn', 'عقب', 'c1db74b2f90ad230b75165ed7e', NULL, 'عَاقَبَ (بلا حرفٍ ولا مفعول)', NULL, 0, 1, '["60:11"]', 'إتيانُ الشيء بعد غيره ← المُعاقَبةُ في الرُّكوب: نَوبةٌ بعد نَوبة ← جاءت نَوبتُكم', 'come after → take turns → your turn came round (and you gained)', 'Not punishment. From عُقۡبَة, a turn (two riders sharing one mount): "then your turn came" (al-Zamakhsharī, al-Ālūsī). Others: "then you took spoils" (Masrūq, al-Zajjāj — in Lisān and Lane).', NULL, '[{"kind": "reading", "label": "your_turn_came", "refs": ["60:11"]}, {"kind": "reading", "label": "you_took_spoils", "refs": ["60:11"]}]', '["tafsir:alusi:60:11", "tafsir:zamakhshari:60:11", "lex:ibn_manzur_lisan_arab:blk_lsn_f0e9cac241bc62e1", "lex:lane_lexicon:blk_lane_4289288c0c41de05", "lex:jawhari_sihah:blk_sih_5b60a18829bff9a9"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عقب:iqab:idafa', 'عقب', 'ef9ac712524e50d06a2a1f98de', NULL, 'صفة + العِقَاب (إضافة)', NULL, 0, 17, '["2:196", "2:211", "3:11", "5:2", "5:98", "6:165", "7:167", "8:13", "8:25", "8:48", "8:52", "13:6", "40:3", "40:22", "41:43", "59:4", "59:7"]', 'ما يأتي عَقِبَ الفعل ← جزاءُ السوء ← تُضافُ إليه صفةُ الله: شديدُه، سريعُه', 'what comes after the deed → punishment, named as the field of God''s severity or speed', 'العِقَاب is always the second noun: after شَدِيدُ (14×), سَرِيعُ (6:165, 7:167) or ذُو (41:43). al-Rāghib: عقاب is kept for punishment. Often forgiveness is named in the same breath (6:165, 7:167, 41:43).', NULL, '[{"kind": "head", "label": "shadid", "refs": ["2:196", "2:211", "3:11", "5:2", "5:98", "8:13", "8:25", "8:48", "8:52", "13:6", "40:3", "40:22", "59:4", "59:7"]}, {"kind": "head", "label": "sari", "refs": ["6:165", "7:167"]}, {"kind": "head", "label": "dhu", "refs": ["41:43"]}]', '["lex:raghib_mufradat:blk_mfr_be172382da8f5c43", "lex:raghib_mufradat:blk_mfr_b1464684a844473a", "lex:ibn_manzur_lisan_arab:blk_lsn_59c16f78a16b0432", "lex:khalil_kitab_ayn:blk_kay_5deec258a12e0f2c", "tafsir:zamakhshari:40:3"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عقب:iqab:mutakallim', 'عقب', 'ef9ac712524e50d06a2a1f98de', NULL, 'عِقَابِ (= عِقَابِي) مضافًا إلى المتكلّم', NULL, 0, 3, '["13:32", "38:14", "40:5"]', 'ما يأتي عَقِبَ الفعل ← بعدَ الإمهال ← عِقابي أنا', 'what comes after → My punishment, that came after the delay', 'The final ي is dropped; عِقَابِ = عِقَابِي (Ibn ʿĀshūr). The setting is a respite first, then the seizing — the root''s "after" shows.', NULL, NULL, '["tafsir:ibn_ashur:13:32", "tafsir:alusi:13:32", "lex:raghib_mufradat:blk_mfr_244787995c113056"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:طول:tawl:dhu', 'طول', '9e553feca8a3dea46195b29917', NULL, 'ذُو / أُولُو + الطَّوْل', NULL, 0, 2, '["9:86", "40:3"]', 'فضلٌ وامتدادٌ في الشيء ← زيادةٌ على الحاجة ← سَعةٌ وفضلٌ لصاحبه', 'length, reach → more than enough → bounty (of God), wealth (of men)', 'ذُو / أُولُو mean "owner(s) of". Of God (40:3): bounty and power — al-Zamakhsharī: الفضل والزيادة. Of men (9:86): people of means — al-Ṭabarī: ذوو الغنى والمال.', NULL, '[{"kind": "owner", "label": "God_bounty", "refs": ["40:3"]}, {"kind": "owner", "label": "men_wealth", "refs": ["9:86"]}]', '["lex:maqayis_lugha:blk_mqy_a2bf5e7a3a2e79d3", "lex:ibn_manzur_lisan_arab:blk_lsn_74675c950261e0fa", "lex:lane_lexicon:blk_lane_004d345d8b413ff6", "tafsir:zamakhshari:40:3", "tafsir:tabari:9:86"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:طول:tawl:object', 'طول', '9e553feca8a3dea46195b29917', NULL, 'اسْتَطَاعَ + طَوْلًا + أَنْ', NULL, 1, 1, '["4:25"]', 'امتداد ← قدرةٌ تبلغُ الشيء ← سَعةُ مالٍ تكفي للمهر', 'reach → enough means to do something (here, to marry)', 'As the object of يَسۡتَطِعۡ the word is the means itself, and أَن يَنكِحَ says what it is for (al-Zajjāj in Lisān: power to pay the dower; Ibn ʿĀshūr: القدرة).', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_74675c950261e0fa", "lex:fayyumi_misbah_munir:blk_msb_f0bc2f345708479a", "tafsir:ibn_ashur:4:25", "tafsir:zamakhshari:4:25"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:طول:tala:ala', 'طول', 'c408b2931b49b13a3118c66791', NULL, 'طَالَ + عَلَى (والفاعلُ زمن)', 'على', 0, 3, '["20:86", "21:44", "57:16"]', 'امتداد ← طالَ الزمن ← امتدَّ عليهم حتى غيَّرهم', 'grow long → time stretched out over them, and they changed', 'In all three the subject is time — الأمد, العهد, العمر — and على puts the people under it. Keep apart the other طال عليه, with a person as subject: "he did him a favour" (al-Jawharī; Lane). That sense does not occur in the Qurʾān.', NULL, NULL, '["lex:lane_lexicon:blk_lane_1f99f468db43f617", "lex:raghib_mufradat:blk_mfr_c94adcdbd7d1a907", "lex:jawhari_sihah:blk_sih_09ef44243219937a", "lex:lane_lexicon:blk_lane_a345ccc635fbb843", "tafsir:ibn_ashur:57:16"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:طول:tatawala:ala', 'طول', '9ecd326ec131b8adfc677468ae', NULL, 'تَطَاوَلَ + عَلَى (والفاعلُ العُمُر)', 'على', 0, 1, '["28:45"]', 'امتداد ← تمادٍ شيئًا بعد شيء ← طالت عليهم الأعمارُ جيلًا بعد جيل', 'stretch long → life drew on and on over them, age after age', 'Form VI adds a long, drawn-out stretching. With a person as subject, تَطَاوَلَ عَلَيۡهِ means "he lorded it over him" (Lisān; al-Miṣbāḥ). Here the subject is ٱلۡعُمُر, so the sense is time, as with طَالَ عَلَيۡهِمُ (Lane on 28:45).', NULL, NULL, '["lex:lane_lexicon:blk_lane_1f99f468db43f617", "lex:ibn_manzur_lisan_arab:blk_lsn_13e03e6a2c4cab49", "lex:fayyumi_misbah_munir:blk_msb_d89bfb01e5e99ad0", "tafsir:alusi:28:45", "tafsir:ibn_ashur:28:45"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:صير:sara:ila', 'صير', '92c86e0a535b58b80a741edc4f', NULL, 'صَارَ / تَصِيرُ + إِلَى', 'إلى', 0, 1, '["42:53"]', 'المآلُ والمرجع ← انتقالٌ من حالٍ إلى حال ← انتهاءٌ إلى اللهِ وحده', 'change state → come to an end → end up with God, and no one else', 'إِلَى ٱللَّهِ is put first for restriction: to God, not to anyone else (al-Ālūsī; Ibn ʿĀshūr). QAC stores this lemma as the inflected تَصِيرُ.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_8dbfe2b2891784a6", "lex:lane_lexicon:blk_lane_435bcbb7e3f6c1a1", "lex:fayyumi_misbah_munir:blk_msb_01a58ba5866f25be", "lex:raghib_mufradat:blk_mfr_d74d1998e1bf8cfd", "lex:raghib_mufradat:blk_mfr_b1eab9a2e6bc0c34", "tafsir:alusi:42:53", "tafsir:ibn_ashur:42:53"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:صير:masir:ila', 'صير', 'a6a5a940211be758e1edae8a66', NULL, 'إِلَى … ٱلْمَصِير', 'إلى', 0, 13, '["2:285", "3:28", "5:18", "14:30", "22:48", "24:42", "31:14", "35:18", "40:3", "42:15", "50:43", "60:4", "64:3"]', 'المآل ← المَصِيرُ مصدرًا: الصَّيرورة ← الرجوعُ إلى الله بالموت والبعث', 'where things end → the return → and it is to God', 'Here المصير is a verbal noun: the going back, by death and raising (al-Ālūsī on 2:285). Lane: مصير implies a change from the earlier state, which مَرۡجِع does not. In 12 of 13 cases إلى + God comes first ("to Him alone"); 14:30 keeps normal order, with the Fire as the end.', NULL, '[{"kind": "word_order", "label": "fronted_to_God", "refs": ["2:285", "3:28", "5:18", "22:48", "24:42", "31:14", "35:18", "40:3", "42:15", "50:43", "60:4", "64:3"]}, {"kind": "word_order", "label": "idafa_to_doer_normal_order", "refs": ["14:30"]}]', '["lex:lane_lexicon:blk_lane_28742a1672cb75fb", "lex:ibn_manzur_lisan_arab:blk_lsn_b38976d594244954", "lex:jawhari_sihah:blk_sih_42e2cc6bb434e087", "lex:jawhari_sihah:blk_sih_45bbf8e2289fc173", "lex:raghib_mufradat:blk_mfr_2353abb98c6e38fd", "tafsir:alusi:2:285"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:صير:masir:bisa', 'صير', 'a6a5a940211be758e1edae8a66', NULL, 'بِئْسَ / سَاءَتْ + ٱلْمَصِير', NULL, 0, 14, '["2:126", "3:162", "4:97", "4:115", "8:16", "9:73", "22:72", "24:57", "48:6", "57:15", "58:8", "64:10", "66:9", "67:6"]', 'المآل ← المَصِيرُ اسمَ مكان: الموضعُ الذي يُصارُ إليه ← وهو مذموم: جهنّم', 'where things end → the place you end in → and it is a bad one', 'After بئس / ساءت the word is a noun of place — the end-place itself; what is blamed (the Fire) is often left unsaid (al-Ālūsī on 2:126). Lisān: أين مصيركم = "where is your home?"', NULL, '[{"kind": "verb_of_blame", "label": "bisa", "refs": ["2:126", "3:162", "8:16", "9:73", "22:72", "24:57", "57:15", "58:8", "64:10", "66:9", "67:6"]}, {"kind": "verb_of_blame", "label": "saat_masiran", "refs": ["4:97", "4:115", "48:6"]}]', '["tafsir:alusi:2:126", "tafsir:alusi:4:97", "lex:ibn_manzur_lisan_arab:blk_lsn_6ac3ee7df1f76300", "lex:qamus_muhit:blk_qms_a690d433d3e81cc5"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:صير:masir:praise', 'صير', 'a6a5a940211be758e1edae8a66', NULL, 'لَهُمْ … جَزَاءً وَمَصِيرًا', 'لـ', 0, 1, '["25:15"]', 'المآل ← المَصِيرُ موضعًا ← منزلٌ طيّبٌ يُصارُ إليه', 'where things end → a good place to end in', 'The praised twin of بِئۡسَ ٱلۡمَصِيرُ: Paradise is both the reward and the place (al-Zamakhsharī: He praised the reward and its place). Lisān: a good dwelling is called مَصِير.', NULL, NULL, '["tafsir:zamakhshari:25:15", "tafsir:alusi:25:15", "lex:ibn_manzur_lisan_arab:blk_lsn_0c9deb51659d2f80"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:66:8:ila', 'ARC:توب:taba:ila', '66:8', 66, 8, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا', 'Believers, turn back to God with a sincere turning', 'إلى names the end of the road: the person leaves the wrong and arrives at God', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:143:ila', 'ARC:توب:taba:ila', '7:143', 7, 143, 'سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ', 'Glory be to You! I turn back to You', 'Mūsā''s own words: even a prophet''s turning is said with إلى', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:54:ila', 'ARC:توب:taba:ila', '2:54', 2, 54, 'فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ', 'so turn back to your Maker', 'the same verse ends فَتَابَ عَلَيۡكُمۡ — they turn to Him, and He turns to them', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:37:ala', 'ARC:توب:taba:ala', '2:37', 2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِ', 'Then Ādam received words from his Lord, and He turned to him in mercy', 'Ādam turned using those words; God''s answer is told with على: He came back to him and accepted him', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:118:ala', 'ARC:توب:taba:ala', '9:118', 9, 118, 'ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْ', 'then He turned to them, so that they would turn back', 'both frames in three words: God''s turning (على) comes first and makes theirs possible', 0, 'tafsir:alusi:9:118', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:117:ala', 'ARC:توب:taba:ala', '9:117', 9, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ', 'God has turned in mercy to the Prophet, the Emigrants and the Helpers', 'al-Rāghib''s own example: تاب الله عليه = He accepted his turning', 0, 'lex:raghib_mufradat:blk_mfr_72ffee1e445b4afe', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:25:70:bare', 'ARC:توب:taba:bare', '25:70', 25, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا', 'except those who turn back, believe, and do good work', 'the verb''s usual company: leaving the wrong, then faith and good work', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:17:bare', 'ARC:توب:taba:bare', '4:17', 4, 17, 'ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡ', 'then turn back soon after — those are the ones God turns to in mercy', 'مِن قَرِيبٍ says when they turn; the second verb, with على, is God''s answer', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:49:11:bare', 'ARC:توب:taba:bare', '49:11', 49, 11, 'وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'and whoever does not turn back — they are the wrongdoers', 'no goal, no particle: the weight is on leaving the wrong', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:3:tawb', 'ARC:توب:tawb:idafa', '40:3', 40, 3, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ', 'Forgiver of sin, Accepter of the turning-back', 'the person brings the turning; the iḍāfa makes it the thing God receives', 1, 'tafsir:zamakhshari:40:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:42:25:qabul', 'ARC:توب:tawba:qabul_an', '42:25', 42, 25, 'وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ', 'He is the One who accepts the turning of His servants and pardons bad deeds', 'the verse itself pairs عن with pardon — the reading al-Ālūsī gives for عن at 9:104', 1, 'tafsir:alusi:9:104', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:90:qabul', 'ARC:توب:tawba:qabul_an', '3:90', 3, 90, 'لَّن تُقۡبَلَ تَوۡبَتُهُمۡ', 'their turning will never be accepted', 'the turning is theirs (iḍāfa to the doers); receiving it is God''s, and here it is refused', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:17:ala_lam', 'ARC:توب:tawba:ala_lam', '4:17', 4, 17, 'إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ', 'God has taken on Himself to accept the turning of those who do wrong out of ignorance', 'على here is not "against" but "owed by": God has promised it', 1, 'tafsir:zamakhshari:4:17', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:18:ala_lam', 'ARC:توب:tawba:ala_lam', '4:18', 4, 18, 'وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ', 'but turning is not for those who go on doing bad deeds until death comes to one of them', 'the لِـ half of the frame, now denied', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:92:min', 'ARC:توب:tawba:min', '4:92', 4, 92, 'فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِ', 'whoever cannot find one must fast two months in a row — a mercy from God', 'مِن turns the word round: the turning is God''s, toward them', 1, 'tafsir:ibn_ashur:4:92', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:66:8:tawba_mutlaq', 'ARC:توب:tawba:mutlaq', '66:8', 66, 8, 'تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا', 'turn back to God with a sincere turning', 'the noun repeats the verb only to carry the describing word', 1, 'tafsir:ibn_ashur:66:8', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:14:7:plain', 'ARC:شدد:shadid:plain', '14:7', 14, 7, 'وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ', 'but if you are ungrateful, My punishment is severe', 'the word stands alone as the predicate: the punishment is what is hard', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:57:25:plain', 'ARC:شدد:shadid:plain', '57:25', 57, 25, 'وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ', 'and We sent down iron, in which there is great force', 'an adjective right after its noun — the force is the strong thing', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:66:6:plain', 'ARC:شدد:shadid:plain', '66:6', 66, 6, 'مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ', 'angels, stern and severe', 'the plural شِدَاد, still describing the noun before it', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:8:13:idafa', 'ARC:شدد:shadid:idafa', '8:13', 8, 13, 'فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'for God is severe in punishment', 'شديد describes God; the iḍāfa says in what — "His punishment is severe"', 1, 'tafsir:zamakhshari:40:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:53:5:idafa', 'ARC:شدد:shadid:idafa', '53:5', 53, 5, 'عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ', 'one mighty in power taught him', 'the same pattern for Jibrīl: the second noun picks the field — his powers', 0, 'lex:raghib_mufradat:blk_mfr_f71d7ce63756b754', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:48:29:ala', 'ARC:شدد:shadid:ala', '48:29', 48, 29, 'وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡ', 'and those with him are firm against the disbelievers, merciful to one another', 'على points the firmness outward; بين turns the mercy inward', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:100:8:lam', 'ARC:شدد:shadid:lam', '100:8', 100, 8, 'وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ', 'and he is fierce in his love of wealth', 'ٱلۡخَيۡر here is wealth; the books split on whether the lām gives the reason or the field', 1, 'tafsir:alusi:100:8', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:47:4:direct', 'ARC:شدد:shadda:direct', '47:4', 47, 4, 'حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ', 'when you have overpowered them, tie the bonds tight', 'the root picture itself: a knot pulled firm', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:38:20:direct', 'ARC:شدد:shadda:direct', '38:20', 38, 20, 'وَشَدَدۡنَا مُلۡكَهُۥ', 'and We made his kingdom strong', 'the same pull, now on a kingdom: nothing in it comes loose', 0, 'lex:ibn_manzur_lisan_arab:blk_lsn_73dd3f1132a4a38a', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:76:28:direct', 'ARC:شدد:shadda:direct', '76:28', 76, 28, 'نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡ', 'We created them and made their frames firm', 'أَسۡر is how the body is bound together; al-Rāghib: its knots made strong', 0, 'lex:raghib_mufradat:blk_mfr_96d1608bef738e9a', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:20:31:bi', 'ARC:شدد:shadda:bi', '20:31', 20, 31, 'ٱشۡدُدۡ بِهِۦٓ أَزۡرِي', 'strengthen my back through him', 'Mūsā asks for Hārūn: the brother is the cord, the back is what is made firm', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:35:bi', 'ARC:شدد:shadda:bi', '28:35', 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ', 'He said: We will strengthen your arm through your brother', 'the answer to 20:31, in the same frame', 0, 'tafsir:ibn_ashur:28:35', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:10:88:ala', 'ARC:شدد:shadda:ala', '10:88', 10, 88, 'رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ', 'Our Lord, wipe out their wealth and seal their hearts, so they do not believe', 'على lays the binding over the hearts, like a lid tied down', 1, 'lex:lane_lexicon:blk_lane_cc65a837c0a94f72', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:16:126:bi', 'ARC:عقب:aqaba:bi', '16:126', 16, 126, 'وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦ', 'If you pay back, pay back only with the like of what was done to you', 'بِـ fixes the measure; the verse then praises patience over even that', 1, 'tafsir:zamakhshari:16:126', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:22:60:bi', 'ARC:عقب:aqaba:bi', '22:60', 22, 60, 'وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُ', 'whoever pays back with the like of what was done to him, and is then wronged again — God will surely help him', 'same frame, same measure: the like, no more', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:60:11:turn', 'ARC:عقب:aqaba:turn', '60:11', 60, 11, 'وَإِن فَاتَكُمۡ شَيۡءٞ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ', 'if any of your wives leaves you for the disbelievers, and then your turn comes round', 'no بِـ and no one punished: the verb falls back on its picture — one thing coming after another', 1, 'tafsir:alusi:60:11', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:6:165:iqab', 'ARC:عقب:iqab:idafa', '6:165', 6, 165, 'إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ', 'your Lord is swift in punishment, and He is forgiving, merciful', 'the punishment follows the deed quickly — and mercy is named in the same breath', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:41:43:iqab', 'ARC:عقب:iqab:idafa', '41:43', 41, 43, 'إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ', 'your Lord is the Owner of forgiveness, and of painful punishment', 'ذُو + عقاب: He holds it, as He holds forgiveness', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:13:32:mutakallim', 'ARC:عقب:iqab:mutakallim', '13:32', 13, 32, 'فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ', 'I gave the disbelievers time, then I seized them — and how was My punishment!', 'first the respite, then the seizing: the punishment comes after, as the root says', 1, 'tafsir:alusi:13:32', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:38:14:mutakallim', 'ARC:عقب:iqab:mutakallim', '38:14', 38, 14, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', 'each of them called the messengers liars, so My punishment came true', 'al-Rāghib quotes فَحَقَّ عِقَابِ under عقاب', 0, 'lex:raghib_mufradat:blk_mfr_244787995c113056', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:3:tawl', 'ARC:طول:tawl:dhu', '40:3', 40, 3, 'شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِ', 'severe in punishment, Lord of bounty', 'set right after severity: the One who punishes also gives far beyond need', 1, 'tafsir:zamakhshari:40:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:86:tawl', 'ARC:طول:tawl:dhu', '9:86', 9, 86, 'ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ', 'the men of means among them asked your leave', 'the same word of men: they had more than enough — and still asked to stay behind', 0, 'tafsir:tabari:9:86', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:25:tawl', 'ARC:طول:tawl:object', '4:25', 4, 25, 'وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ', 'whoever of you lacks the means to marry free believing women', 'طَوۡل here is the reach of one''s purse', 1, 'tafsir:ibn_ashur:4:25', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:57:16:ala', 'ARC:طول:tala:ala', '57:16', 57, 16, 'وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡ', 'and not be like those given the Book before, for whom time grew long, and their hearts hardened', 'the long stretch of time lies over them — and the hardening follows from it', 1, 'tafsir:ibn_ashur:57:16', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:21:44:ala', 'ARC:طول:tala:ala', '21:44', 21, 44, 'بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُ', 'We let these people and their fathers enjoy life until their lifetimes grew long', 'a long life, felt as something resting on them', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:20:86:ala', 'ARC:طول:tala:ala', '20:86', 20, 86, 'أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ', 'did the time seem too long to you?', 'Mūsā''s question: the wait was short, yet they acted as if it had dragged on', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:45:tatawala', 'ARC:طول:tatawala:ala', '28:45', 28, 45, 'وَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُ', 'But We raised up generations, and life drew on and on over them', 'many generations, a long stretch — and what Mūsā brought was forgotten (Ibn ʿĀshūr)', 1, 'tafsir:ibn_ashur:28:45', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:42:53:sara', 'ARC:صير:sara:ila', '42:53', 42, 53, 'أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ', 'Truly, all matters end up with God', 'the sūra''s last words: every affair, whatever path it takes, arrives at Him', 1, 'tafsir:alusi:42:53', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:285:masir', 'ARC:صير:masir:ila', '2:285', 2, 285, 'غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ', 'Your forgiveness, our Lord — and to You is the return', 'the believers'' own words: the road ends at God', 1, 'tafsir:alusi:2:285', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:64:3:masir', 'ARC:صير:masir:ila', '64:3', 64, 3, 'وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ', 'He shaped you and made your shapes good, and to Him is the return', 'He began you, and He is where you end', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:14:30:masir', 'ARC:صير:masir:ila', '14:30', 14, 30, 'قُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ', 'Say: enjoy yourselves — your road ends in the Fire', 'the same frame turned round: the ending is theirs, and the Fire is where it goes', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:126:masir_bisa', 'ARC:صير:masir:bisa', '2:126', 2, 126, 'ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'then I will drive him to the punishment of the Fire — and what a wretched end!', 'after بئس the word is the place; the Fire just named is what is blamed', 1, 'tafsir:alusi:2:126', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:97:masir_bisa', 'ARC:صير:masir:bisa', '4:97', 4, 97, 'فَأُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا', 'those — their shelter is Hell, and how bad a place to end!', 'ساءت works like بئس; مَصِيرًا says in what way it is bad', 0, 'tafsir:alusi:4:97', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:25:15:masir_praise', 'ARC:صير:masir:praise', '25:15', 25, 15, 'أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَآءٗ وَمَصِيرٗا', 'or the Garden of Eternity promised to the mindful? It is their reward and their journey''s end', 'a reward needs a good place to be enjoyed in; مَصِير names that place', 1, 'tafsir:zamakhshari:25:15', 1);
